/// Every dimension, in logical pixels, for one platform and density.
class NDMetrics {
  const NDMetrics({
    required this.space0,
    required this.space1,
    required this.space2,
    required this.space3,
    required this.space4,
    required this.space6,
    required this.space8,
    required this.space12,
    required this.space16,
    required this.space24,
    required this.rhythm1,
    required this.rhythm2,
    required this.rhythm3,
    required this.rhythm4,
    required this.rhythm5,
    required this.rhythm10,
    required this.radiusSm,
    required this.radiusMd,
    required this.radiusLg,
    required this.radiusXl,
    required this.radius2xl,
    required this.radiusPill,
    required this.sizeIcon,
    required this.sizeIconMd,
    required this.sizeIconLg,
    required this.sizeBrand,
    required this.sizeHomeArtMax,
    required this.sizeHomeArtCenteredMax,
    required this.sizeFeaturedCardMin,
    required this.sizeDirectionCardMin,
    required this.sizeDockTile,
    required this.sizeDockIcon,
    required this.sizeDockMax,
    required this.markPip,
    required this.markDot,
    required this.markNode,
    required this.markDotLg,
    required this.markStroke,
    required this.borderWidthNone,
    required this.borderWidthThin,
    required this.borderWidthMedium,
    required this.borderWidthThick,
    required this.focusWidth,
    required this.focusGap,
    required this.sizeControlSm,
    required this.sizeControlMd,
    required this.sizeControlLg,
    required this.sizeField,
    required this.sizeTargetMin,
  });

  final double space0;
  final double space1;
  final double space2;
  final double space3;
  final double space4;
  final double space6;
  final double space8;
  final double space12;
  final double space16;
  final double space24;
  final double rhythm1;
  final double rhythm2;
  final double rhythm3;
  final double rhythm4;
  final double rhythm5;
  final double rhythm10;
  final double radiusSm;
  final double radiusMd;
  final double radiusLg;
  final double radiusXl;
  final double radius2xl;
  final double radiusPill;
  final double sizeIcon;
  final double sizeIconMd;
  final double sizeIconLg;
  final double sizeBrand;
  final double sizeHomeArtMax;
  final double sizeHomeArtCenteredMax;
  final double sizeFeaturedCardMin;
  final double sizeDirectionCardMin;
  final double sizeDockTile;
  final double sizeDockIcon;
  final double sizeDockMax;
  /// A 3 px pip and lane.
  final double markPip;
  /// The small dot and its 5 px lane: kickers, the page bar, rails.
  final double markDot;
  /// A 9 px node on a time line.
  final double markNode;
  /// The 15 px dot at a heading's, a rail's or a foot's end.
  final double markDotLg;
  /// The stroke of drawn controls: a menu's bars, a chevron, a disclosure's plus.
  final double markStroke;
  final double borderWidthNone;
  final double borderWidthThin;
  final double borderWidthMedium;
  final double borderWidthThick;
  /// Focus outline width (WCAG 2.2 2.4.13: at least a 2 px perimeter).
  final double focusWidth;
  /// Space between a control and its focus outline, filled with surface.base.
  final double focusGap;
  final double sizeControlSm;
  final double sizeControlMd;
  final double sizeControlLg;
  final double sizeField;
  final double sizeTargetMin;

  static NDMetrics resolve(NDPlatform platform, NDDensity density) => switch ((platform, density)) {
        (NDPlatform.ios, NDDensity.comfortable) => iosComfortable,
        (NDPlatform.ios, NDDensity.compact) => iosCompact,
        (NDPlatform.android, NDDensity.comfortable) => androidComfortable,
        (NDPlatform.android, NDDensity.compact) => androidCompact,
        (NDPlatform.desktop, NDDensity.comfortable) => desktopComfortable,
