/// Numbers: opacity, leading, tracking (em), stacking, springs.
abstract final class NDNumbers {
  /// A disabled control (WCAG exempts it from contrast).
  static const double opacityDisabled = 0.4;
  static const double opacityMuted = 0.6;
  static const double opacitySubtle = 0.16;
  /// Scrim behind a dialog.
  static const double opacityOverlay = 0.55;
  static const double textLeadingDisplay = 1.06;
  static const double textLeadingH1 = 1.1;
  static const double textLeadingH2 = 1.15;
  static const double textLeadingH3 = 1.22;
  static const double textLeadingH4 = 1.3;
  static const double textLeadingBodyLg = 1.55;
  static const double textLeadingBody = 1.6;
  static const double textLeadingLabel = 1.4;
  static const double textLeadingCaption = 1.3;
  static const double scriptLeadingAr = 1.8;
  static const double scriptLeadingZh = 1.75;
  /// Display headings.
  static const double trackingTight = -0.02; // em
  static const double trackingSnug = -0.01; // em
  static const double trackingNormal = 0.0; // em
  static const double trackingLoose = 0.02; // em
  static const double trackingWide = 0.04; // em
  /// Upper-case labels and kickers.
  static const double trackingWider = 0.06; // em
  static const double springStandardStiffness = 380.0;
  static const double springStandardDampingRatio = 0.8;
  static const double springGentleStiffness = 200.0;
  static const double springGentleDampingRatio = 1.0;
  static const double springSnappyStiffness = 700.0;
  static const double springSnappyDampingRatio = 0.9;
  static const double zBase = 0.0;
  static const double zRaised = 10.0;
  static const double zSticky = 100.0;
  static const double zOverlay = 200.0;
  static const double zDialog = 300.0;
  static const double zToast = 400.0;
  static const double zSkip = 1000.0;
  static const double artGlow = 0.4;
}

/// Font weights.
abstract final class NDWeights {
  static const FontWeight weightRegular = FontWeight.w400;
  static const FontWeight weightMedium = FontWeight.w500;
  static const FontWeight weightSemibold = FontWeight.w600;
}

/// Font families per platform, most preferred first. The app declares the fonts it bundles.
abstract final class NDFonts {
  static List<String> stack(NDFontFamily family, NDPlatform platform) => switch ((family, platform)) {
        (NDFontFamily.sans, NDPlatform.ios) => const ['IBM Plex Sans', '.AppleSystemUIFont'],
        (NDFontFamily.sans, NDPlatform.android) => const ['IBM Plex Sans', 'Roboto'],
        (NDFontFamily.sans, NDPlatform.desktop) => const ['IBM Plex Sans', 'IBM Plex Sans Fallback', 'system-ui', '-apple-system', 'Segoe UI', 'Roboto', 'Helvetica Neue', 'Arial', 'sans-serif'],
        (NDFontFamily.sansAr, NDPlatform.ios) => const ['IBM Plex Sans Arabic', '.AppleSystemUIFont'],
        (NDFontFamily.sansAr, NDPlatform.android) => const ['IBM Plex Sans Arabic', 'Noto Sans Arabic'],
        (NDFontFamily.sansAr, NDPlatform.desktop) => const ['IBM Plex Sans Arabic', 'IBM Plex Sans', 'IBM Plex Sans Fallback', 'system-ui', 'Segoe UI', 'Tahoma', 'Arial', 'sans-serif'],
        (NDFontFamily.sansZh, NDPlatform.ios) => const ['PingFang SC'],
        (NDFontFamily.sansZh, NDPlatform.android) => const ['Noto Sans CJK SC'],
        (NDFontFamily.sansZh, NDPlatform.desktop) => const ['IBM Plex Sans', 'Noto Sans SC', 'IBM Plex Sans Fallback', 'system-ui', 'PingFang SC', 'Microsoft YaHei', 'sans-serif'],
        (NDFontFamily.mono, NDPlatform.ios) => const ['SF Mono', 'Menlo'],
        (NDFontFamily.mono, NDPlatform.android) => const ['monospace'],
        (NDFontFamily.mono, NDPlatform.desktop) => const ['ui-monospace', 'SFMono-Regular', 'Menlo', 'Consolas', 'Liberation Mono', 'monospace'],
      };
}

/// Durations.
abstract final class NDDurations {
  static Duration durationUiFast(NDMotion motion) => switch (motion) {
        NDMotion.standard => const Duration(milliseconds: 150),
        NDMotion.reduced => const Duration(milliseconds: 0),
      };
  static Duration durationUi(NDMotion motion) => switch (motion) {
        NDMotion.standard => const Duration(milliseconds: 250),
        NDMotion.reduced => const Duration(milliseconds: 0),
      };
  static Duration durationScene(NDMotion motion) => switch (motion) {
        NDMotion.standard => const Duration(milliseconds: 450),
        NDMotion.reduced => const Duration(milliseconds: 0),
      };
  static Duration durationSceneSlow(NDMotion motion) => switch (motion) {
        NDMotion.standard => const Duration(milliseconds: 900),
        NDMotion.reduced => const Duration(milliseconds: 0),
      };
}

/// Easing curves.
abstract final class NDEasings {
  /// The standard easing of interface motion.
  static const Cubic easing = Cubic(0.2, 0.7, 0.2, 1.0);
  /// Decelerate: something arriving.
  static const Cubic easingEnter = Cubic(0.0, 0.0, 0.2, 1.0);
  /// Accelerate: something leaving.
  static const Cubic easingExit = Cubic(0.4, 0.0, 1.0, 1.0);
  /// A larger, more noticeable change.
  static const Cubic easingEmphasized = Cubic(0.2, 0.0, 0.0, 1.0);
}

/// One layer of a shadow, in logical pixels.
class NDShadowLayer {
  const NDShadowLayer(this.color, this.x, this.y, this.blur, this.spread, {this.inset = false});

  final Color color;
  final double x;
  final double y;
  final double blur;
  final double spread;
  final bool inset;

  /// Flutter draws outer shadows only; an inset layer has none.
  BoxShadow? toBoxShadow() => inset
      ? null
      : BoxShadow(color: color, offset: Offset(x, y), blurRadius: blur, spreadRadius: spread);
}

abstract final class NDShadows {
  static List<NDShadowLayer> elevation1(NDTheme theme) => switch (theme) {
        NDTheme.light => const [NDShadowLayer(Color(0x1F000000), 0.0, 1.0, 3.0, 0.0)],
        NDTheme.dark => const [NDShadowLayer(Color(0x99000000), 0.0, 1.0, 2.0, 0.0)],
        NDTheme.lightContrast => const [NDShadowLayer(Color(0x1F000000), 0.0, 1.0, 3.0, 0.0)],
        NDTheme.darkContrast => const [NDShadowLayer(Color(0x99000000), 0.0, 1.0, 2.0, 0.0)],
      };
  static List<NDShadowLayer> elevation2(NDTheme theme) => switch (theme) {
        NDTheme.light => const [NDShadowLayer(Color(0x1F000000), 0.0, 6.0, 16.0, 0.0)],
        NDTheme.dark => const [NDShadowLayer(Color(0xB3000000), 0.0, 4.0, 12.0, 0.0)],
        NDTheme.lightContrast => const [NDShadowLayer(Color(0x1F000000), 0.0, 6.0, 16.0, 0.0)],
        NDTheme.darkContrast => const [NDShadowLayer(Color(0xB3000000), 0.0, 4.0, 12.0, 0.0)],
      };
  static List<NDShadowLayer> elevation3(NDTheme theme) => switch (theme) {
        NDTheme.light => const [NDShadowLayer(Color(0x29000000), 0.0, 16.0, 40.0, 0.0)],
        NDTheme.dark => const [NDShadowLayer(Color(0xCC000000), 0.0, 12.0, 32.0, 0.0)],
        NDTheme.lightContrast => const [NDShadowLayer(Color(0x29000000), 0.0, 16.0, 40.0, 0.0)],
        NDTheme.darkContrast => const [NDShadowLayer(Color(0xCC000000), 0.0, 12.0, 32.0, 0.0)],
      };
}

/// The faces this package bundles as font assets (OFL-1.1, fonts/OFL-IBM-Plex.txt); Chinese and
/// monospace use the system faces.
abstract final class NDBundledFonts {
  static const String package = 'nddev_opennetwork_design_system';
  static const Set<NDFontFamily> families = {NDFontFamily.sans, NDFontFamily.sansAr};
}

/// A text style on a platform: family, size, line height as a multiple of the size, weight, letter
/// spacing as a share of the size (em), case, and the Material 3 role it fills.
class NDTextStyle {
  const NDTextStyle(
    this.family,
    this.size,
    this.lineHeight,
    this.weight,
    this.tracking,
    this.uppercase,
    this.material,
  );

  final NDFontFamily family;
  final double size;
  final double lineHeight;
  final int weight;
  final double tracking;
  final bool uppercase;
  final String? material;

  /// The style of a role on a platform, adjusted for the script of the text.
  static NDTextStyle resolve(NDTypeRole role, NDPlatform platform, [NDScript script = NDScript.latin]) {
    final base = _base(role, platform);
    return NDTextStyle(
      base.family == NDFontFamily.sans ? script.family : base.family,
      base.size,
      role.isBody ? (script.bodyLeading ?? base.lineHeight) : base.lineHeight,
      base.weight,
      script.tracksLetters ? base.tracking : 0,
      script.hasCase && base.uppercase,
      base.material,
    );
  }

  static NDTextStyle _base(NDTypeRole role, NDPlatform platform) => switch ((role, platform)) {
        (NDTypeRole.display, NDPlatform.ios) => const NDTextStyle(NDFontFamily.sans, 34.0, 1.06, 400, -0.02, false, 'displaySmall'),
        (NDTypeRole.display, NDPlatform.android) => const NDTextStyle(NDFontFamily.sans, 36.0, 1.06, 400, -0.02, false, 'displaySmall'),
        (NDTypeRole.display, NDPlatform.desktop) => const NDTextStyle(NDFontFamily.sans, 40.0, 1.06, 400, -0.02, false, 'displaySmall'),
        (NDTypeRole.h1, NDPlatform.ios) => const NDTextStyle(NDFontFamily.sans, 28.0, 1.1, 400, -0.01, false, 'headlineLarge'),
        (NDTypeRole.h1, NDPlatform.android) => const NDTextStyle(NDFontFamily.sans, 32.0, 1.1, 400, -0.01, false, 'headlineLarge'),
        (NDTypeRole.h1, NDPlatform.desktop) => const NDTextStyle(NDFontFamily.sans, 32.0, 1.1, 400, -0.01, false, 'headlineLarge'),
        (NDTypeRole.h2, NDPlatform.ios) => const NDTextStyle(NDFontFamily.sans, 22.0, 1.15, 400, -0.01, false, 'headlineMedium'),
        (NDTypeRole.h2, NDPlatform.android) => const NDTextStyle(NDFontFamily.sans, 28.0, 1.15, 400, -0.01, false, 'headlineMedium'),
        (NDTypeRole.h2, NDPlatform.desktop) => const NDTextStyle(NDFontFamily.sans, 28.0, 1.15, 400, -0.01, false, 'headlineMedium'),
        (NDTypeRole.h3, NDPlatform.ios) => const NDTextStyle(NDFontFamily.sans, 20.0, 1.22, 400, -0.01, false, 'headlineSmall'),
        (NDTypeRole.h3, NDPlatform.android) => const NDTextStyle(NDFontFamily.sans, 24.0, 1.22, 400, -0.01, false, 'headlineSmall'),
        (NDTypeRole.h3, NDPlatform.desktop) => const NDTextStyle(NDFontFamily.sans, 22.0, 1.22, 400, -0.01, false, 'headlineSmall'),
        (NDTypeRole.h4, NDPlatform.ios) => const NDTextStyle(NDFontFamily.sans, 17.0, 1.3, 400, -0.01, false, 'titleLarge'),
        (NDTypeRole.h4, NDPlatform.android) => const NDTextStyle(NDFontFamily.sans, 22.0, 1.3, 400, -0.01, false, 'titleLarge'),
        (NDTypeRole.h4, NDPlatform.desktop) => const NDTextStyle(NDFontFamily.sans, 18.0, 1.3, 400, -0.01, false, 'titleLarge'),
        (NDTypeRole.lead, NDPlatform.ios) => const NDTextStyle(NDFontFamily.sans, 17.0, 1.55, 400, 0.0, false, 'bodyLarge'),
        (NDTypeRole.lead, NDPlatform.android) => const NDTextStyle(NDFontFamily.sans, 16.0, 1.55, 400, 0.0, false, 'bodyLarge'),
        (NDTypeRole.lead, NDPlatform.desktop) => const NDTextStyle(NDFontFamily.sans, 16.0, 1.55, 400, 0.0, false, 'bodyLarge'),
        (NDTypeRole.body, NDPlatform.ios) => const NDTextStyle(NDFontFamily.sans, 16.0, 1.6, 400, 0.0, false, 'bodyMedium'),
        (NDTypeRole.body, NDPlatform.android) => const NDTextStyle(NDFontFamily.sans, 14.0, 1.6, 400, 0.0, false, 'bodyMedium'),
        (NDTypeRole.body, NDPlatform.desktop) => const NDTextStyle(NDFontFamily.sans, 14.0, 1.6, 400, 0.0, false, 'bodyMedium'),
        (NDTypeRole.label, NDPlatform.ios) => const NDTextStyle(NDFontFamily.sans, 15.0, 1.4, 400, 0.0, false, 'labelLarge'),
        (NDTypeRole.label, NDPlatform.android) => const NDTextStyle(NDFontFamily.sans, 14.0, 1.4, 400, 0.0, false, 'labelLarge'),
        (NDTypeRole.label, NDPlatform.desktop) => const NDTextStyle(NDFontFamily.sans, 13.0, 1.4, 400, 0.0, false, 'labelLarge'),
        (NDTypeRole.kicker, NDPlatform.ios) => const NDTextStyle(NDFontFamily.sans, 15.0, 1.4, 400, 0.06, true, 'labelLarge'),
        (NDTypeRole.kicker, NDPlatform.android) => const NDTextStyle(NDFontFamily.sans, 14.0, 1.4, 400, 0.06, true, 'labelLarge'),
        (NDTypeRole.kicker, NDPlatform.desktop) => const NDTextStyle(NDFontFamily.sans, 13.0, 1.4, 400, 0.06, true, 'labelLarge'),
        (NDTypeRole.caption, NDPlatform.ios) => const NDTextStyle(NDFontFamily.sans, 12.0, 1.3, 400, 0.0, false, 'bodySmall'),
        (NDTypeRole.caption, NDPlatform.android) => const NDTextStyle(NDFontFamily.sans, 12.0, 1.3, 400, 0.0, false, 'bodySmall'),
        (NDTypeRole.caption, NDPlatform.desktop) => const NDTextStyle(NDFontFamily.sans, 12.0, 1.3, 400, 0.0, false, 'bodySmall'),
        (NDTypeRole.code, NDPlatform.ios) => const NDTextStyle(NDFontFamily.mono, 15.2, 1.6, 400, 0.0, false, 'bodyMedium'),
        (NDTypeRole.code, NDPlatform.android) => const NDTextStyle(NDFontFamily.mono, 13.3, 1.6, 400, 0.0, false, 'bodyMedium'),
        (NDTypeRole.code, NDPlatform.desktop) => const NDTextStyle(NDFontFamily.mono, 13.3, 1.6, 400, 0.0, false, 'bodyMedium'),
      };

  /// A Flutter text style: the family's stack on the platform, its size, weight, line height and
  /// letter spacing. A bundled family is this package's font asset; upper case is applied to the
  /// string by the widget (Flutter has no text transform).
  TextStyle toTextStyle(NDPlatform platform) {
    final stack = NDFonts.stack(family, platform);
    return TextStyle(
      fontFamily: stack.first,
      package: NDBundledFonts.families.contains(family) ? NDBundledFonts.package : null,
      fontFamilyFallback: stack.skip(1).toList(),
      fontSize: size,
      fontWeight: FontWeight.values.firstWhere(
        (w) => w.value >= weight,
        orElse: () => FontWeight.w900,
      ),
      height: lineHeight,
      letterSpacing: tracking * size,
      leadingDistribution: TextLeadingDistribution.even,
    );
  }
}

/// The kit's component colours: aliases of the semantic roles.
extension NDComponentColors on NDColors {
  /// app-bar.fill → surface.base
  Color get appBarFill => surfaceBase;
